#!/usr/bin/env bash
# Reproduce experiment EXP-003. Generated by experiment-runner.
set -euo pipefail
cd "$(dirname "$0")"

mkdir -p runs

# Sanity gate
uv run python code/run.py --seed 0 --config sanity \
  --out "runs/$(date -u +%Y%m%dT%H%M%SZ)_sanity_s0.jsonl"

# Multi-seed sweep
for seed in 42 123 456; do
  uv run python code/run.py --seed "$seed" --config full \
    --out "runs/$(date -u +%Y%m%dT%H%M%SZ)_full_s${seed}.jsonl"
done

echo "done"
